let state=loadState();state.gallery=state.gallery||structuredClone(defaults.gallery);state.socialLinks=state.socialLinks||{facebook:'',instagram:''};let currentMonth=new Date(2026,11,1);let activePanel='overview';let selectedBookingId=null;let galleryIndex=0;let galleryTimer=null;let apiMode=false;let apiCsrf='';const demoQuery=new URLSearchParams(location.search);const demoReviewEnabled=demoQuery.get('demo')==='1';const demoOwnerRoute=demoQuery.get('owner')==='1';
function loadState(){try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(!s)return structuredClone(defaults);const savedTrips=Array.isArray(s.trips)?s.trips:[];const mergedTrips=defaults.trips.map(base=>{const old=savedTrips.find(t=>t.id===base.id);if(!old)return base;const options=base.options?base.options.map(option=>({...option,...(old.options?.find(saved=>saved.label===option.label)||{})})).concat((old.options||[]).filter(option=>!base.options.some(def=>def.label===option.label))):old.options;return {...base,...old,options:options||base.options,endDate:old.endDate||base.endDate}});return {...structuredClone(defaults),...s,trips:[...mergedTrips,...savedTrips.filter(t=>!defaults.trips.some(base=>base.id===t.id))]}}catch{return structuredClone(defaults)}}
function saveState(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(n){return 'R'+Number(n||0).toLocaleString('en-ZA')}
function tripById(id){return state.trips.find(t=>t.id===id)}
function notify(msg){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.append(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function renderGallery(){const stage=document.querySelector('#galleryStage'),dots=document.querySelector('#galleryDots');if(!stage||!dots)return;const posts=state.gallery||[];if(!posts.length){stage.innerHTML='<div class="gallery-empty">Trip photos and videos will appear here.</div>';dots.innerHTML='';return}galleryIndex=(galleryIndex+posts.length)%posts.length;const post=posts[galleryIndex],media=post.type==='video'?`<video src="${esc(post.src)}" controls playsinline preload="metadata" aria-label="${esc(post.caption||'Nyathi Tours trip video')}"></video>`:`<img src="${esc(post.src)}" alt="${esc(post.caption||'Nyathi Tours trip moment')}"/>`;stage.innerHTML=`<div class="gallery-slide"><div class="gallery-media">${media}<span class="gallery-count">${String(galleryIndex+1).padStart(2,'0')} / ${String(posts.length).padStart(2,'0')}</span></div><div class="gallery-caption"><span>NYATHI TOURS JOURNAL</span><p>${esc(post.caption||'A moment from the road.')}</p></div></div>`;dots.innerHTML=posts.map((_,i)=>`<button type="button" class="gallery-dot ${i===galleryIndex?'active':''}" data-gallery-index="${i}" aria-label="Go to gallery item ${i+1}"></button>`).join('');dots.querySelectorAll('[data-gallery-index]').forEach(b=>b.onclick=()=>{galleryIndex=Number(b.dataset.galleryIndex);renderGallery()});if(galleryTimer)clearInterval(galleryTimer);if(posts.length>1&&post.type!=='video')galleryTimer=setInterval(()=>{galleryIndex=(galleryIndex+1)%posts.length;renderGallery()},6500)}
function renderSocialDock(){const dock=document.querySelector('#socialDock');if(!dock)return;const urls=state.socialLinks||{};const valid=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};const fb=valid(urls.facebook),ig=valid(urls.instagram);dock.innerHTML=`<a class="social-icon whatsapp" href="https://wa.me/27733047351?text=Hi%20Nyathi%20Tours%2C%20I%27d%20like%20to%20ask%20about%20your%20trips." target="_blank" rel="noopener noreferrer" aria-label="Chat with Nyathi Tours on WhatsApp"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 11.8a8.4 8.4 0 0 1-12.4 7.4L3 20.5l1.3-4.9A8.5 8.5 0 1 1 20.5 11.8Z"/><path d="M8.4 7.6c.2-.4.5-.4.8-.4h.4c.2 0 .4.1.5.4l.8 1.9c.1.2.1.4 0 .6l-.6.8c-.2.2-.2.4 0 .7.5.8 1.2 1.5 2 2 .3.2.5.2.7 0l.8-.7c.2-.2.4-.2.6-.1l1.9.9c.3.1.4.3.4.5 0 .8-.4 1.5-1 1.8-.7.5-1.6.7-2.6.4-1.2-.4-2.7-1.2-4.1-2.6-1.4-1.4-2.2-2.9-2.5-4.1-.3-.9-.1-1.7.4-2.1Z"/></svg></a><a class="social-icon facebook ${fb?'':'is-unset'}" href="${fb||'#social-facebook'}" ${fb?'target="_blank" rel="noopener noreferrer"':'aria-disabled="true" title="Add the Facebook profile link in the owner area"'} aria-label="Nyathi Tours on Facebook"><span aria-hidden="true">f</span></a><a class="social-icon instagram ${ig?'':'is-unset'}" href="${ig||'#social-instagram'}" ${ig?'target="_blank" rel="noopener noreferrer"':'aria-disabled="true" title="Add the Instagram profile link in the owner area"'} aria-label="Nyathi Tours on Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle class="insta-dot" cx="17.5" cy="6.7" r="1"/></svg></a>`;dock.querySelectorAll('.is-unset').forEach(a=>a.onclick=e=>{e.preventDefault();notify('Add the official social profile link in Owner area → Gallery & socials.')})}
function resizeTripPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read that photo.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('That photo could not be opened.'));img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.76))};img.src=reader.result};reader.readAsDataURL(file)})}
function showTripPhotoPreview(src){const box=document.querySelector('#tripImagePreview');if(!box)return;box.querySelector('img').src=src;box.classList.remove('hidden')}
async function apiRequest(action,data=null,method=data===null?'GET':'POST'){const opts={method,credentials:'same-origin',headers:{}};if(method==='GET'){}else{opts.headers['Content-Type']='application/json';if(apiCsrf)opts.headers['X-CSRF-Token']=apiCsrf;opts.body=JSON.stringify(data||{})}const res=await fetch(`nyathi-api.php?action=${encodeURIComponent(action)}`,opts),body=await res.json().catch(()=>({ok:false,error:'The server returned an unreadable response.'}));if(!res.ok||!body.ok)throw new Error(body.error||'The request could not be completed.');return body}
async function apiUpload(file){const data=new FormData();data.append('media',file);const res=await fetch('nyathi-api.php?action=media.upload',{method:'POST',credentials:'same-origin',headers:apiCsrf?{'X-CSRF-Token':apiCsrf}:{},body:data}),body=await res.json().catch(()=>({ok:false,error:'The server returned an unreadable response.'}));if(!res.ok||!body.ok)throw new Error(body.error||'Could not upload this file.');return body.url}
async function apiUploadOptimized(file){if(file.type.startsWith('image/')){const dataUrl=await resizeTripPhoto(file),blob=await (await fetch(dataUrl)).blob();return apiUpload(new File([blob],'nyathi-upload.jpg',{type:'image/jpeg'}))}return apiUpload(file)}
async function loadOwnerFromApi(){const res=await apiRequest('dashboard');state={...state,...res.data};renderTrips();renderOwner(activePanel)}
function updateDemoOwnerAccess(){const entry=document.querySelector('#demoReviewEntry');if(entry)entry.classList.toggle('hidden',!demoReviewEnabled||apiMode)}
async function syncPublicFromApi(){try{const remote=await apiRequest('public');apiMode=true;state.trips=remote.trips||[];state.gallery=remote.gallery||[];state.socialLinks=remote.socialLinks||{facebook:'',instagram:''};state.reviews=remote.reviews||[];renderTrips()}catch{/* Local prototype keeps its sample data when no PHP backend is configured. */}finally{updateDemoOwnerAccess()}}
async function handleOwnerLogin(event){event.preventDefault();const form=event.currentTarget,fd=new FormData(form),feedback=document.querySelector('#loginFeedback');feedback.textContent='';if(['localhost','127.0.0.1','::1'].includes(location.hostname)){showOwnerDashboard();return}try{const result=await apiRequest('login',{email:fd.get('email'),password:fd.get('password'),role:fd.get('role')});apiCsrf=result.csrf;apiMode=true;await loadOwnerFromApi();form.reset();showOwnerDashboard()}catch(err){feedback.textContent=err.message||'Unable to sign in right now.'}}
function renderPromo(){const el=document.querySelector('#promoBanner');const p=state.promotions.find(x=>x.active);if(!el)return;if(!p){el.classList.add('hidden');el.innerHTML='';return}el.classList.remove('hidden');el.innerHTML=`${esc(p.text)} <button aria-label="Dismiss promotion" id="promoDismiss">×</button>`;el.style.cssText='background:#f1b843;color:#14233d;text-align:center;padding:9px 36px;font-size:12px;font-weight:700;position:relative';const b=el.querySelector('button');b.style.cssText='position:absolute;right:14px;top:5px;border:0;background:none;font-size:18px;cursor:pointer;color:#14233d';b.onclick=()=>el.classList.add('hidden')}
function bookedSeats(tripId,date){return state.bookings.filter(b=>b.trip===tripId&&b.status==='accepted'&&(!date||b.date===date)).reduce((n,b)=>n+Number(b.seats||1),0)}
function availableSeats(trip,date){if(date&&trip?.startDate===date&&trip?.availableSeats!==null&&trip?.availableSeats!==undefined&&Number.isFinite(Number(trip.availableSeats)))return Number(trip.availableSeats);return Number.isFinite(Number(trip?.capacity))&&Number(trip.capacity)>0?Math.max(0,Number(trip.capacity)-bookedSeats(trip.id,date)):null}
function renderAvailability(){const t=tripById(document.querySelector('#clientTrip')?.value),date=document.querySelector('#clientDate')?.value,seat=document.querySelector('#clientBookingForm input[name=seats]'),note=document.querySelector('#seatAvailability');if(!t||!note)return;const remaining=availableSeats(t,date);if(remaining===null){note.textContent='Ask Nyathi Tours to confirm available seats for this date.';if(seat){seat.removeAttribute('max');seat.disabled=false}}else{note.textContent=remaining?`${remaining} seat${remaining===1?'':'s'} available for this date.`:'This departure is full. Please ask about another date.';if(seat){seat.max=String(remaining||1);seat.disabled=remaining===0}}}
function renderTrips(){const grid=document.querySelector('#tripGrid');grid.innerHTML=state.trips.filter(t=>t.visible).map((t,i)=>{const remaining=t.startDate?availableSeats(t,t.startDate):null;const seatsText=remaining===null?'Ask us about seats':remaining?`${remaining} seats available`:'Fully booked';return `<article class="trip-card"><div class="trip-image"><img src="${esc(t.image)}" alt="${esc(t.name)}"/><span class="trip-number">0${i+1} / ${esc(t.tag)}</span></div><div class="trip-card-content"><h3>${esc(t.name)}</h3><p class="trip-summary">${esc(t.summary)}</p><div class="trip-meta"><span>${esc(t.duration)}</span><span>${esc(t.dateLabel)}</span><span class="seat-status">${Number(t.capacity)>0?esc(seatsText):'Ask us about seats'}</span></div><details class="trip-detail"><summary>Package details</summary><p>${esc(t.detail||'Contact Nyathi Tours for package details.')}</p></details><div class="trip-price"><div><small>PRICE PER PERSON</small><strong>${esc(t.priceText||money(t.price))}</strong></div><a href="#booking" data-trip-booking="${esc(t.id)}">Book / enquire ↗</a></div></div></article>`}).join('');grid.querySelectorAll('[data-trip-booking]').forEach(a=>a.addEventListener('click',()=>populateBookingForm(a.dataset.tripBooking)));const sel=document.querySelector('#reviewForm select[name=trip]');if(sel)sel.innerHTML='<option value="">Choose a trip</option>'+state.trips.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');populateBookingForm();renderCalendar();renderPromo();renderApprovedReviews();renderGallery();renderSocialDock()}
function populateBookingForm(id){const tripSelect=document.querySelector('#clientTrip'),packageSelect=document.querySelector('#clientPackage');if(!tripSelect||!packageSelect)return;const trips=state.trips.filter(t=>t.visible);tripSelect.innerHTML=trips.length?trips.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join(''):'<option value="">No trips available right now</option>';if(id&&trips.some(t=>t.id===id))tripSelect.value=id;const t=tripById(tripSelect.value)||trips[0];if(!t){packageSelect.innerHTML='<option value="">No packages available</option>';packageSelect.disabled=true;document.querySelector('#clientDate').value='';renderAvailability();return}packageSelect.disabled=false;const options=t.options?.length?t.options:[{label:`Standard package · ${t.priceText||money(t.price)} per person`,price:t.price}];packageSelect.innerHTML=options.map((o,i)=>`<option value="${i}" data-price="${Number(o.price)}" data-deposit="${Number(o.deposit||0)}">${esc(o.label)}</option>`).join('');document.querySelector('#clientDate').value=t.startDate||'';renderAvailability()}
function waUrl(msg){return 'https://wa.me/27733047351?text='+encodeURIComponent(msg)}
function renderCalendar(){const grid=document.querySelector('#calendarDays');if(!grid)return;const year=currentMonth.getFullYear(),month=currentMonth.getMonth();const label=currentMonth.toLocaleDateString('en-ZA',{month:'long',year:'numeric'});document.querySelector('#monthLabel').textContent=label;const first=new Date(year,month,1),days=new Date(year,month+1,0).getDate();let mondayOffset=(first.getDay()+6)%7;let html='';for(let i=0;i<mondayOffset;i++)html+='<span></span>';for(let day=1;day<=days;day++){const date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const trips=state.trips.filter(t=>t.visible&&t.startDate&&t.startDate<=date&&(!t.endDate||t.endDate>=date));html+=`<button class="${trips.length?'has-event':''}" data-date="${date}" aria-label="${date}${trips.length?' trip date':''}">${day}</button>`}grid.innerHTML=html;grid.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const trips=state.trips.filter(t=>t.visible&&t.startDate&&t.startDate<=b.dataset.date&&(!t.endDate||t.endDate>=b.dataset.date));grid.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelector('#calendarEvent').textContent=trips.length?trips.map(t=>`${t.name} · ${t.dateLabel} · ${t.priceText}`).join(' / '):'No published departure on this date. Ask us about other dates.'}));document.querySelector('#calendarEvent').textContent=state.trips.some(t=>t.visible&&t.startDate&&t.startDate<=`${year}-${String(month+1).padStart(2,'0')}-30`&&(!t.endDate||t.endDate>=`${year}-${String(month+1).padStart(2,'0')}-30`))?'30 Dec · New Year by the Sea · R7 500 per person':'Select a marked date to see trip details.'}
function renderApprovedReviews(){const el=document.querySelector('#approvedReviews');if(!el)return;const reviews=state.reviews.filter(r=>r.status==='approved');el.innerHTML=reviews.length?reviews.map(r=>`<article class="review-card"><div class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>“${esc(r.body)}”</p><small>${esc(r.name)} · ${esc(tripById(r.trip)?.name||'Nyathi Tours')}</small></article>`).join(''):'<div class="empty-state">Guest stories will appear here after the Nyathi Tours team reviews them.</div>'}
function showOwner(){document.querySelector('#publicSite').classList.add('hidden');document.querySelector('.site-header').classList.add('hidden');document.querySelector('#promoBanner').classList.add('hidden');document.querySelector('.site-footer').classList.add('hidden');document.querySelector('#socialDock').classList.add('hidden');document.querySelector('#ownerShell').classList.add('hidden');document.querySelector('#ownerLogin').classList.remove('hidden');document.body.classList.add('owner-mode');window.scrollTo(0,0)}
function showOwnerDashboard(){document.querySelector('#ownerLogin').classList.add('hidden');document.querySelector('#ownerShell').classList.remove('hidden');renderOwner(activePanel);window.scrollTo(0,0)}
function showPublic(){document.querySelector('#ownerShell').classList.add('hidden');document.querySelector('#ownerLogin').classList.add('hidden');document.querySelector('#publicSite').classList.remove('hidden');document.querySelector('.site-header').classList.remove('hidden');document.querySelector('.site-footer').classList.remove('hidden');document.querySelector('#socialDock').classList.remove('hidden');document.body.classList.remove('owner-mode');renderPromo();window.scrollTo(0,0)}
function renderOwner(panel){activePanel=panel;document.querySelectorAll('.owner-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));const el=document.querySelector('#ownerPanel');if(panel==='overview')el.innerHTML=ownerOverview();if(panel==='trips')el.innerHTML=ownerTrips();if(panel==='gallery')el.innerHTML=ownerGallery();if(panel==='bookings')el.innerHTML=ownerBookings();if(panel==='invoices')el.innerHTML=ownerInvoices();if(panel==='reviews')el.innerHTML=ownerReviews();bindOwnerPanel();bindRequestPanel();bindGalleryPanel()}
function ownerOverview(){let next=state.trips.filter(t=>t.startDate).sort((a,b)=>a.startDate.localeCompare(b.startDate))[0];return `<div class="dashboard-grid"><div class="stat-card"><small>LIVE TRIPS</small><strong>${state.trips.filter(t=>t.visible).length}</strong></div><div class="stat-card"><small>UPCOMING DATES</small><strong>${state.trips.filter(t=>t.startDate).length}</strong></div><div class="stat-card"><small>BOOKING REQUESTS</small><strong>${state.bookings.filter(b=>b.status==='pending').length}</strong></div><div class="stat-card"><small>REVIEWS TO APPROVE</small><strong>${state.reviews.filter(r=>r.status==='pending').length}</strong></div></div><div class="owner-columns"><div class="owner-card"><h2>Next on the calendar</h2>${next?`<ul class="owner-list"><li><b>${esc(next.name)}</b><span>${esc(next.dateLabel)}</span></li></ul>`:'<p>No upcoming dates added yet.</p>'}<p>Keep departure dates and trip details current so guests know what’s available.</p><button class="mini-button primary" data-go="trips">Manage trips & dates →</button></div><div class="owner-card"><h2>Quick actions</h2><div class="inline-actions"><button class="mini-button primary" data-go="bookings">Review booking requests</button><button class="mini-button" data-go="invoices">View invoices</button><button class="mini-button" data-go="reviews">Review guest feedback</button></div><div class="owner-promotions"><h2>Website promotion</h2><form id="promoForm" class="owner-form"><label class="wide">Promotion message<input name="text" maxlength="120" placeholder="Example: Summer departures now open" required/></label><label><input type="checkbox" name="active" checked/> Publish on site</label><button class="mini-button primary" type="submit">Save promotion</button></form><p>Saved promotions appear in the notice bar on the public site.</p></div></div></div>`}
function ownerTrips(){return `<div class="owner-grid"><div class="owner-card"><h2 class="owner-subhead">Add or edit a trip</h2><form id="tripForm" class="owner-form"><input name="id" type="hidden"/><label>Trip name<input name="name" required placeholder="e.g. Bilene Lagoon Escape"/></label><label>Duration<input name="duration" required placeholder="3 nights · 4 days"/></label><label>Price per person (R)<input name="price" type="number" min="0" required placeholder="4850"/></label><label>Trip capacity (seats)<input name="capacity" type="number" min="1" placeholder="Optional; leave blank if not set"/></label><label>Departure date<input name="date" type="date"/></label><label>Return date<input name="endDate" type="date"/></label><label>Trip tag<input name="tag" placeholder="LAGOON ESCAPE"/></label><label class="wide">Pickup points<input name="pickup" placeholder="Nelspruit · Gauteng"/></label><label class="wide">Short description<textarea name="summary" rows="2" required></textarea></label><label class="wide">What guests should know<textarea name="detail" rows="3" placeholder="Inclusions, exclusions, accommodation, meals, terms"></textarea></label><label class="wide">Trip photo<input name="image" type="file" accept="image/*"/><small class="form-note">Choose a photo from your device. A smaller copy is saved in this browser preview.</small></label><div class="trip-image-preview wide hidden" id="tripImagePreview"><img alt="Selected trip preview"/><button class="mini-button" id="removeTripImage" type="button">Remove selected photo</button></div><div class="wide inline-actions"><button class="button button-ink" type="submit">Save trip to this preview</button><button class="mini-button" id="tripFormReset" type="button">Clear form</button></div></form></div><div class="owner-card"><h2 class="owner-subhead">Trips & dates</h2><table class="owner-table"><thead><tr><th>TRIP</th><th>DATES</th><th>PRICE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${state.trips.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.startDate?(t.startDate+(t.endDate?' – '+t.endDate:'')):'Ask for dates')}</td><td>${money(t.price)}</td><td>${t.visible?'Published':'Hidden'}</td><td><div class="inline-actions"><button class="mini-button" data-edit-trip="${esc(t.id)}">Edit</button><button class="mini-button" data-toggle-trip="${esc(t.id)}">${t.visible?'Hide':'Publish'}</button></div></td></tr>`).join('')}</tbody></table><p class="form-note">This preview saves changes in this browser only. A live, secure dashboard will need a database and owner login.</p></div></div>`}
function ownerGallery(){return `<div class="owner-grid"><div class="owner-card"><h2 class="owner-subhead">Share a trip moment</h2><p>Add a photo or a short video from a Nyathi Tours trip. It will appear in the public gallery carousel.</p><form id="galleryUploadForm" class="owner-form"><label class="wide">Photo or video<input name="media" type="file" accept="image/*,video/*" required/></label><label class="wide">Caption<textarea name="caption" rows="2" maxlength="180" placeholder="A little story from the road…"></textarea></label><button class="button button-ink wide" type="submit">Add to gallery</button></form><p class="form-note">Prototype uploads are stored in this browser only. Photos are resized; video clips are limited to 1.2 MB here. Live hosting will use proper media storage.</p><h2 class="owner-subhead" style="margin-top:28px">Social profile links</h2><form id="socialLinksForm" class="owner-form"><label class="wide">Facebook page URL<input name="facebook" type="url" value="${esc(state.socialLinks.facebook||'')}" placeholder="https://facebook.com/your-page"/></label><label class="wide">Instagram profile URL<input name="instagram" type="url" value="${esc(state.socialLinks.instagram||'')}" placeholder="https://instagram.com/your-profile"/></label><button class="mini-button primary wide" type="submit">Save social links</button></form></div><div class="owner-card"><h2 class="owner-subhead">Gallery posts · ${state.gallery.length}</h2>${state.gallery.length?`<div class="gallery-owner-list">${state.gallery.map((p,i)=>`<article class="gallery-owner-item"><div class="gallery-owner-thumb">${p.type==='video'?`<video src="${esc(p.src)}" muted preload="metadata"></video>`:`<img src="${esc(p.src)}" alt=""/>`}</div><div><span class="status-pill">${p.type==='video'?'VIDEO':'PHOTO'} · ${i+1}</span><p>${esc(p.caption||'No caption')}</p></div><button class="mini-button" data-delete-gallery="${esc(p.id)}" aria-label="Remove gallery post">Remove</button></article>`).join('')}</div>`:'<div class="empty-state">Your trip photos and videos will appear here after you add them.</div>'}</div></div>`}
function ownerBookings(){const active=state.bookings.find(b=>b.id===selectedBookingId)||state.bookings.find(b=>b.status==='pending')||state.bookings[0];if(active)selectedBookingId=active.id;const t=active&&tripById(active.trip);const invoice=active&&state.invoices.find(i=>i.id===active.invoiceId);let detail='<div class="empty-state">Client booking requests will appear here for review. Accepting a request creates its linked invoice.</div>';if(active){const requestInfo=`<p><b>Request:</b> ${esc(active.requestNumber||'—')}<br/><b>Trip:</b> ${esc(t?.name||'Trip')} · ${esc(active.packageLabel||'Package')}<br/><b>Preferred date:</b> ${esc(active.date||'To be confirmed')}<br/><b>Pickup:</b> ${esc(active.pickup||'To be confirmed')}<br/><b>Travellers:</b> ${Number(active.seats||1)}<br/><b>Contact:</b> ${esc(active.phone||'')}${active.email?' · '+esc(active.email):''}<br/><b>Notes:</b> ${esc(active.notes||'—')}</p>`;let statusContent;if(active.status==='pending')statusContent=`<form id="requestPriceForm" class="owner-form"><label>Confirm price per person (R)<input name="unitPrice" type="number" min="1" value="${Number(active.requestedPrice||t?.price||0)}" required/></label><div class="wide inline-actions"><button class="button button-ink" type="submit">Accept request & create invoice</button><button class="mini-button" id="declineRequest" type="button">Decline request</button></div></form><p class="form-note">Review the date, package option and price before accepting.</p>`;else if(active.status==='accepted'&&invoice)statusContent=`<div class="request-success">Request accepted. Invoice <b>${esc(invoice.number)}</b> is linked to this booking for <b>${money(invoice.total)}</b>.</div><div class="inline-actions" style="margin-top:12px"><button class="mini-button primary" data-print-invoice="${esc(invoice.id)}">Print invoice</button><button class="mini-button" id="copyRequestConfirmation">Copy booking confirmation</button></div><div class="confirmation-preview">BOOKING CONFIRMATION<br/>${esc(active.name)} · ${esc(t?.name||'Nyathi Tours')}<br/>Date: ${esc(active.date||t?.dateLabel||'To be confirmed')} · Pickup: ${esc(active.pickup||'To be confirmed')}<br/>Travellers: ${Number(active.seats||1)} · Invoice: ${esc(invoice.number)} · Amount due: ${money(invoice.total)}</div>`;else if(active.status==='confirmed'||active.status==='accepted')statusContent=`<div class="empty-state">This booking was already accepted before invoice linking was added. Create its invoice now.</div><form id="legacyInvoiceForm" class="owner-form"><label>Confirm price per person (R)<input name="unitPrice" type="number" min="1" value="${Number(active.finalPricePerPerson||active.requestedPrice||t?.price||0)}" required/></label><button class="button button-ink" type="submit">Create linked invoice</button></form>`;else statusContent='<div class="empty-state">This request was declined. No invoice was created.</div>';detail=`<div class="request-detail"><h3>${esc(active.name)} <span class="status-pill">${esc(active.status)}</span></h3>${requestInfo}${statusContent}</div>`}return `<div class="request-layout"><div class="owner-card"><h2 class="owner-subhead">Client booking requests</h2>${state.bookings.length?`<table class="owner-table"><thead><tr><th>REQUEST</th><th>CLIENT</th><th>TRIP</th><th>STATUS</th><th></th></tr></thead><tbody>${state.bookings.map(b=>`<tr><td>${esc(b.requestNumber||'—')}</td><td>${esc(b.name)}</td><td>${esc(tripById(b.trip)?.name||'Trip')}</td><td><span class="status-pill">${esc(b.status)}</span></td><td><button class="mini-button" data-review-request="${esc(b.id)}">Review</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">No client requests yet. New requests from the website will appear here.</div>'}</div><div class="owner-card"><h2 class="owner-subhead">Review & respond</h2>${detail}</div></div>`}
function ownerInvoices(){return `<div class="owner-card"><h2 class="owner-subhead">Invoices linked to accepted bookings</h2><p>Accepting a client request creates an invoice from the final per-person price and number of travellers.</p>${state.invoices.length?`<table class="owner-table"><thead><tr><th>INVOICE</th><th>CLIENT / BOOKING</th><th>TRIP</th><th>TOTAL</th><th>STATUS</th><th></th></tr></thead><tbody>${state.invoices.map(i=>{const b=state.bookings.find(x=>x.id===i.bookingId);return `<tr><td>${esc(i.number)}</td><td>${esc(i.client)}<br/><small>${esc(b?.requestNumber||'')}</small></td><td>${esc(tripById(i.trip)?.name||'Trip')}</td><td>${money(i.total)}</td><td>${esc(i.status)}</td><td><button class="mini-button" data-print-invoice="${esc(i.id)}">Print</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty-state">No invoices yet. They’ll be created when you accept a booking request.</div>'}<p class="form-note">Invoice layout is a prototype. Confirm official business and tax details before issuing real invoices.</p></div>`}
async function acceptBookingRequest(id,unitPrice){const b=state.bookings.find(x=>x.id===id);if(!b||!['pending','confirmed','accepted'].includes(b.status)||b.invoiceId||!Number.isFinite(unitPrice)||unitPrice<1)return;if(apiMode){try{await apiRequest('booking.accept',{id:Number(id),price:unitPrice});await loadOwnerFromApi();notify('Booking accepted and invoice created.')}catch(err){notify(err.message)}return}const t=tripById(b.trip),remaining=availableSeats(t,b.date);if(remaining!==null&&Number(b.seats||1)>remaining){notify(`Only ${remaining} seat(s) remain for that departure.`);return}const n=String(state.invoices.length+1).padStart(4,'0');const invoice={id:'invoice-'+Date.now(),number:`NT-${new Date().getFullYear()}-${n}`,bookingId:b.id,client:b.name,contact:b.email||b.phone,trip:b.trip,date:new Date().toISOString().slice(0,10),total:unitPrice*Number(b.seats||1),paid:0,depositRequired:Number(b.requestedDeposit||0),pricePerPerson:unitPrice,itemDescription:`${Number(b.seats||1)} traveller(s) · ${b.packageLabel||t?.name||'Tour package'}`,note:'Payment instructions to be confirmed by Nyathi Tours.',status:'Unpaid'};b.status='accepted';b.finalPricePerPerson=unitPrice;b.invoiceId=invoice.id;b.acceptedAt=new Date().toISOString();state.invoices.unshift(invoice);saveState();selectedBookingId=b.id;renderOwner('bookings');notify('Booking accepted and linked invoice created.')}
function confirmationText(b){const t=tripById(b.trip),i=state.invoices.find(x=>x.id===b.invoiceId);return `NYATHI TOURS BOOKING CONFIRMATION\nRequest: ${b.requestNumber}\nGuest: ${b.name}\nTrip: ${t?.name||'Nyathi Tours'}\nPackage: ${b.packageLabel||'Tour package'}\nDate: ${b.date||t?.dateLabel||'To be confirmed'}\nPickup: ${b.pickup||'To be confirmed'}\nTravellers: ${b.seats}\nInvoice: ${i?.number||'—'}\nTotal: ${money(i?.total||0)}\nNyathi Tours: +27 73 304 7351`}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Copied to clipboard.')}catch{notify('Clipboard is not available in this preview.')}}
function renderClientEmail(b){const t=tripById(b.trip),i=state.invoices.find(x=>x.id===b.invoiceId),panel=document.querySelector('#clientEmailPreview');if(!panel||!i)return;panel.innerHTML=`<div class="email-preview"><div class="email-preview-head"><img src="nyathi-logo.jpg" alt="Nyathi Tours"/><span>BOOKING EMAIL · DESIGN PREVIEW</span></div><div class="email-preview-body"><div class="email-accent"></div><h4>Your trip is taking shape.</h4><p>Hi ${esc(b.name)},</p><p>Your booking request has been accepted. Here are the details for your Nyathi Tours trip:</p><p><b>${esc(t?.name||'Nyathi Tours journey')}</b><br/>${esc(b.packageLabel||'Package')}<br/>Date: ${esc(b.date||t?.dateLabel||'To be confirmed')}<br/>Pickup: ${esc(b.pickup||'To be confirmed')}<br/>Travellers: ${Number(b.seats||1)}</p><p>Invoice <b>${esc(i.number)}</b> · Total ${money(i.total)}${i.depositRequired?` · Deposit to secure your place ${money(i.depositRequired)}`:''}</p><span class="email-button">YOUR INVOICE IS READY</span><p>Thank you for choosing Nyathi Tours. We look forward to welcoming you.</p></div><div class="email-preview-foot">Nyathi Tours · +27 73 304 7351 · musa@nyathitours.co.za<br/>Design preview only — email sending is not connected yet.</div></div>`;panel.scrollIntoView({behavior:'smooth',block:'nearest'})}
function bindRequestPanel(){const form=document.querySelector('#requestPriceForm')||document.querySelector('#legacyInvoiceForm');if(form)form.onsubmit=e=>{e.preventDefault();acceptBookingRequest(selectedBookingId,Number(new FormData(form).get('unitPrice')))};const decline=document.querySelector('#declineRequest');if(decline)decline.onclick=async()=>{const b=state.bookings.find(x=>x.id===selectedBookingId);if(!b)return;try{if(apiMode){await apiRequest('booking.decline',{id:Number(b.id)});await loadOwnerFromApi()}else{b.status='declined';b.declinedAt=new Date().toISOString();saveState();renderOwner('bookings')}notify('Booking request declined.')}catch(err){notify(err.message)}};document.querySelectorAll('[data-review-request]').forEach(b=>b.onclick=()=>{selectedBookingId=b.dataset.reviewRequest;renderOwner('bookings')});document.querySelectorAll('[data-print-invoice]').forEach(b=>b.onclick=()=>{const i=state.invoices.find(x=>x.id===b.dataset.printInvoice);if(i)printInvoice(i)});const copy=document.querySelector('#copyRequestConfirmation');const b=state.bookings.find(x=>x.id===selectedBookingId);if(copy&&b)copy.onclick=()=>copyText(confirmationText(b));if(copy&&b){const row=copy.parentElement;const emailButton=document.createElement('button');emailButton.className='mini-button';emailButton.type='button';emailButton.textContent='Preview branded email';emailButton.onclick=()=>renderClientEmail(b);row.append(emailButton);const emailPanel=document.createElement('div');emailPanel.id='clientEmailPreview';document.querySelector('.request-detail').append(emailPanel)}}
function ownerReviews(){return `<div class="owner-card"><h2 class="owner-subhead">Review submissions</h2><div class="review-moderation">${state.reviews.length?state.reviews.map(r=>`<article class="moderation-card"><div class="inline-actions"><span class="status-pill">${esc(r.status)}</span><span class="stars">${'★'.repeat(r.rating)}</span></div><p>“${esc(r.body)}”</p><small>${esc(r.name)} · ${esc(tripById(r.trip)?.name||'Trip')}</small><div class="inline-actions" style="margin-top:12px">${r.status==='pending'?`<button class="mini-button primary" data-approve-review="${esc(r.id)}">Approve for website</button>`:''}<button class="mini-button" data-delete-review="${esc(r.id)}">Remove</button></div></article>`).join(''):'<div class="empty-state">No guest reviews submitted yet.</div>'}</div></div>`}
function bindOwnerPanel(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>renderOwner(b.dataset.go));const promoForm=document.querySelector('#promoForm');if(promoForm)promoForm.onsubmit=e=>{e.preventDefault();const fd=new FormData(promoForm);state.promotions.unshift({text:fd.get('text'),active:fd.get('active')==='on'});state.promotions=state.promotions.slice(0,5);saveState();renderTrips();renderOwner('overview');notify('Promotion saved in this preview.')};const tripForm=document.querySelector('#tripForm');if(tripForm){const imageInput=tripForm.elements.image;imageInput.onchange=async()=>{const file=imageInput.files?.[0];if(file){try{showTripPhotoPreview(await resizeTripPhoto(file))}catch(err){notify(err.message)}}};tripForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(tripForm),id=fd.get('id');let trip=id?tripById(id):null;try{if(apiMode){const image=imageInput.files?.[0]?await apiUploadOptimized(imageInput.files[0]):(trip?.image||'coast-aerial.jpg');await apiRequest('trip.save',{id:id||'trip-'+Date.now(),name:fd.get('name'),tag:fd.get('tag')||'NEW JOURNEY',summary:fd.get('summary'),duration:fd.get('duration'),price:Number(fd.get('price')),priceText:`from ${money(fd.get('price'))}`,startDate:fd.get('date'),endDate:fd.get('endDate'),capacity:fd.get('capacity')?Number(fd.get('capacity')):null,pickup:fd.get('pickup'),detail:fd.get('detail'),image,visible:trip?trip.visible:true,options:trip?.options||[]});await loadOwnerFromApi();notify(id?'Trip updated.':'Trip added.');return}const image=imageInput.files?.[0]?await resizeTripPhoto(imageInput.files[0]):(trip?.image||'coast-aerial.jpg');if(!trip){trip={id:'trip-'+Date.now(),image,visible:true};state.trips.push(trip)}Object.assign(trip,{image,capacity:fd.get('capacity')?Number(fd.get('capacity')):null,name:fd.get('name'),tag:fd.get('tag')||'NEW JOURNEY',summary:fd.get('summary'),duration:fd.get('duration'),price:Number(fd.get('price')),priceText:`from ${money(fd.get('price'))}`,startDate:fd.get('date'),endDate:fd.get('endDate'),dateLabel:fd.get('date')?(fd.get('endDate')?`${fd.get('date')} – ${fd.get('endDate')}`:fd.get('date')):'Ask for next dates',pickup:fd.get('pickup'),detail:fd.get('detail')});saveState();renderTrips();renderOwner('trips');notify(id?'Trip updated in this preview.':'Trip added in this preview.')}catch(err){notify(err.message||'Could not save this trip photo.')}};document.querySelectorAll('[data-edit-trip]').forEach(b=>b.onclick=()=>{const t=tripById(b.dataset.editTrip),f=document.querySelector('#tripForm');if(!t||!f)return;f.elements.id.value=t.id;f.elements.name.value=t.name;f.elements.duration.value=t.duration;f.elements.price.value=t.price;f.elements.capacity.value=t.capacity||'';f.elements.date.value=t.startDate||'';f.elements.endDate.value=t.endDate||'';f.elements.tag.value=t.tag||'';f.elements.pickup.value=t.pickup||'';f.elements.summary.value=t.summary||'';f.elements.detail.value=t.detail||'';f.elements.image.value='';showTripPhotoPreview(t.image);f.scrollIntoView({behavior:'smooth',block:'center'})});document.querySelectorAll('[data-toggle-trip]').forEach(b=>b.onclick=async()=>{const t=tripById(b.dataset.toggleTrip);if(!t)return;try{if(apiMode){await apiRequest('trip.save',{...t,visible:!t.visible});await loadOwnerFromApi()}else{t.visible=!t.visible;saveState();renderTrips();renderOwner('trips')}}catch(err){notify(err.message)}});const resetTrip=document.querySelector('#tripFormReset');if(resetTrip)resetTrip.onclick=()=>{tripForm.reset();document.querySelector('#tripImagePreview').classList.add('hidden')};const removePhoto=document.querySelector('#removeTripImage');if(removePhoto)removePhoto.onclick=()=>{imageInput.value='';document.querySelector('#tripImagePreview').classList.add('hidden')}}const bookingForm=document.querySelector('#bookingForm');if(bookingForm)bookingForm.onsubmit=e=>{e.preventDefault();const fd=new FormData(bookingForm);const booking={id:'booking-'+Date.now(),name:fd.get('name'),phone:fd.get('phone'),trip:fd.get('trip'),date:fd.get('date'),pickup:fd.get('pickup'),seats:Number(fd.get('seats')),deposit:Number(fd.get('deposit')),payment:fd.get('payment'),status:'pending'};state.bookings.unshift(booking);saveState();renderOwner('bookings');showConfirmation(booking.id);notify('Booking saved in this preview.')};document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>showConfirmation(b.dataset.confirm));document.querySelectorAll('[data-delete-booking]').forEach(b=>b.onclick=()=>{state.bookings=state.bookings.filter(x=>x.id!==b.dataset.deleteBooking);saveState();renderOwner('bookings')});const invoiceForm=document.querySelector('#invoiceForm');if(invoiceForm)invoiceForm.onsubmit=e=>{e.preventDefault();const fd=new FormData(invoiceForm);const n=String(state.invoices.length+1).padStart(4,'0');const invoice={id:'inv-'+Date.now(),number:`NT-${new Date().getFullYear()}-${n}`,client:fd.get('client'),contact:fd.get('contact'),trip:fd.get('trip'),date:fd.get('date'),total:Number(fd.get('total')),paid:Number(fd.get('paid')),note:fd.get('note'),status:Number(fd.get('paid'))>=Number(fd.get('total'))?'Paid':Number(fd.get('paid'))>0?'Partly paid':'Unpaid'};state.invoices.unshift(invoice);saveState();renderOwner('invoices');printInvoice(invoice);notify('Invoice prepared in this preview.')};document.querySelectorAll('[data-approve-review]').forEach(b=>b.onclick=async()=>{try{if(apiMode){await apiRequest('review.moderate',{id:Number(b.dataset.approveReview),status:'approved'});await loadOwnerFromApi()}else{const r=state.reviews.find(x=>x.id===b.dataset.approveReview);if(r)r.status='approved';saveState();renderOwner('reviews');renderApprovedReviews()}}catch(err){notify(err.message)}});document.querySelectorAll('[data-delete-review]').forEach(b=>b.onclick=async()=>{try{if(apiMode){await apiRequest('review.moderate',{id:Number(b.dataset.deleteReview),status:'removed'});await loadOwnerFromApi()}else{state.reviews=state.reviews.filter(x=>x.id!==b.dataset.deleteReview);saveState();renderOwner('reviews')}}catch(err){notify(err.message)}})}
function readMediaUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read that file.'));reader.readAsDataURL(file)})}
function bindGalleryPanel(){const form=document.querySelector('#galleryUploadForm');if(form)form.onsubmit=async e=>{e.preventDefault();const file=form.elements.media.files?.[0];if(!file)return;if(!file.type.startsWith('image/')&&!file.type.startsWith('video/'))return notify('Choose an image or video file.');if(file.type.startsWith('video/')&&file.size>(apiMode?18874368:1258291))return notify(apiMode?'That video is larger than the 18 MB upload limit.':'This local preview accepts videos up to 1.2 MB.');try{const caption=form.elements.caption.value.trim();if(apiMode){const url=await apiUploadOptimized(file);await apiRequest('gallery.save',{url,caption});await loadOwnerFromApi();notify('Trip moment added to the shared gallery.');return}const type=file.type.startsWith('video/')?'video':'image',src=type==='image'?await resizeTripPhoto(file):await readMediaUrl(file),post={id:'gallery-'+Date.now(),type,src,caption};state.gallery.unshift(post);try{saveState()}catch(err){state.gallery.shift();throw new Error('Browser storage is full. Remove an old gallery post or use a smaller file.')}galleryIndex=0;renderGallery();renderOwner('gallery');notify('Trip moment added to the gallery preview.')}catch(err){notify(err.message||'Could not add this media file.')}};document.querySelectorAll('[data-delete-gallery]').forEach(b=>b.onclick=async()=>{try{if(apiMode){await apiRequest('gallery.delete',{id:Number(b.dataset.deleteGallery)});await loadOwnerFromApi()}else{state.gallery=state.gallery.filter(post=>post.id!==b.dataset.deleteGallery);saveState();galleryIndex=0;renderGallery();renderOwner('gallery')}}catch(err){notify(err.message)}});const socials=document.querySelector('#socialLinksForm');if(socials)socials.onsubmit=async e=>{e.preventDefault();const fd=new FormData(socials),facebook=String(fd.get('facebook')||'').trim(),instagram=String(fd.get('instagram')||'').trim();const valid=value=>{if(!value)return true;try{return ['https:','http:'].includes(new URL(value).protocol)}catch{return false}};if(!valid(facebook)||!valid(instagram))return notify('Enter a valid Facebook or Instagram profile URL.');try{if(apiMode)await apiRequest('social.save',{facebook,instagram});else{state.socialLinks={facebook,instagram};saveState()}state.socialLinks={facebook,instagram};renderSocialDock();notify(apiMode?'Social links saved.':'Social links saved in this browser preview.')}catch(err){notify(err.message)}}}
function showConfirmation(id){const b=state.bookings.find(x=>x.id===id);if(!b)return;if(b.status!=='confirmed'){b.status='confirmed';saveState()}renderOwner('bookings');const t=tripById(b.trip);const when=b.date?new Date(`${b.date}T12:00:00`).toLocaleDateString('en-ZA',{day:'numeric',month:'long',year:'numeric'}):(t?.dateLabel||'To be confirmed');const el=document.querySelector('#confirmationPreview');if(!el)return;el.innerHTML=`<div class="confirmation-preview"><b>BOOKING CONFIRMATION · ${esc(b.name)}</b><br/>Trip: ${esc(t?.name||'Nyathi Tours journey')}<br/>Date: ${esc(when)}<br/>Pickup: ${esc(b.pickup||t?.pickup||'To be confirmed')}<br/>Seats: ${b.seats}<br/>Deposit recorded: ${money(b.deposit)}<br/>${esc(b.payment||'Please contact Nyathi Tours to confirm payment details.')}<br/><div class="inline-actions" style="margin-top:12px"><button class="mini-button" id="copyConfirmation">Copy text</button></div></div>`;document.querySelector('#copyConfirmation').onclick=async()=>{const text=`NYATHI TOURS BOOKING CONFIRMATION\nGuest: ${b.name}\nTrip: ${t?.name}\nDate: ${when}\nPickup: ${b.pickup||t?.pickup}\nSeats: ${b.seats}\nDeposit recorded: ${money(b.deposit)}\nContact Nyathi Tours for final trip details.`;try{await navigator.clipboard.writeText(text);notify('Confirmation copied.')}catch{notify('Clipboard not available in this preview.')}}}
function printInvoice(i){const t=tripById(i.trip),remaining=Math.max(0,i.total-i.paid);let root=document.querySelector('#invoicePrint');if(!root){root=document.createElement('div');root.id='invoicePrint';root.className='invoice-print';document.body.append(root)}root.innerHTML=`<div class="print-invoice"><div class="invoice-header"><img class="invoice-logo" src="nyathi-logo.jpg" alt="Nyathi Tours"/><div class="invoice-contact">+27 73 304 7351<br/>+27 72 551 2910<br/>musa@nyathitours.co.za</div></div><h1>INVOICE</h1><p><b>Invoice no:</b> <span class="invoice-number">${esc(i.number)}</span><br/><b>Booking request:</b> ${esc(state.bookings.find(b=>b.id===i.bookingId)?.requestNumber||'—')}<br/><b>Date:</b> ${esc(i.date)}<br/><b>Bill to:</b> ${esc(i.client)}<br/><b>Contact:</b> ${esc(i.contact||'—')}</p><table><tr><th>Description</th><th>Amount</th></tr><tr><td>${esc(i.itemDescription||t?.name||'Tour package')}<br/><small>${esc(t?.name||'')}</small></td><td>${money(i.total)}</td></tr></table><p><b>Total:</b> ${money(i.total)}<br/><b>Paid:</b> ${money(i.paid)}<br/><b>Balance due:</b> ${money(remaining)}${i.depositRequired?`<br/><b>Deposit required to secure booking:</b> ${money(i.depositRequired)}`:''}</p><div class="payment-placeholder"><b>Payment details · DEMO PLACEHOLDERS</b><br/>Bank: [ADD BANK NAME]<br/>Account name: [ADD ACCOUNT NAME]<br/>Account number: [ADD ACCOUNT NUMBER]<br/>Branch code: [ADD BRANCH CODE]<br/>Payment reference: ${esc(i.number)}</div><p>${esc(i.note||'Please contact Nyathi Tours to confirm payment arrangements.')}</p><footer class="invoice-footer">Thank you for choosing Nyathi Tours. We look forward to welcoming you.</footer><small>Prototype invoice. Replace demo payment placeholders and confirm official invoice requirements before sending.</small></div>`;setTimeout(()=>window.print(),100)}
document.querySelector('#ownerOpen').addEventListener('click',e=>{e.preventDefault();showOwner()});document.querySelector('#ownerLoginForm').addEventListener('submit',handleOwnerLogin);document.querySelector('#loginBack').addEventListener('click',showPublic);document.querySelector('#loginBrandHome').addEventListener('click',e=>{e.preventDefault();showPublic()});document.querySelector('#ownerClose').addEventListener('click',showPublic);document.querySelector('#ownerLogout').addEventListener('click',async()=>{try{if(apiCsrf)await apiRequest('logout',{});apiCsrf='';showPublic();notify('You have signed out.')}catch(err){notify(err.message)}});document.querySelector('#ownerBrandHome').addEventListener('click',e=>{e.preventDefault();showPublic()});document.querySelectorAll('.owner-tabs button').forEach(b=>b.addEventListener('click',()=>renderOwner(b.dataset.panel)));document.querySelector('#galleryPrev').addEventListener('click',()=>{galleryIndex=(galleryIndex+(state.gallery.length||1)-1)%(state.gallery.length||1);renderGallery()});document.querySelector('#galleryNext').addEventListener('click',()=>{galleryIndex=(galleryIndex+1)%(state.gallery.length||1);renderGallery()});document.querySelector('#prevMonth').addEventListener('click',()=>{currentMonth=new Date(currentMonth.getFullYear(),currentMonth.getMonth()-1,1);renderCalendar()});document.querySelector('#nextMonth').addEventListener('click',()=>{currentMonth=new Date(currentMonth.getFullYear(),currentMonth.getMonth()+1,1);renderCalendar()});document.querySelector('#clientTrip').addEventListener('change',()=>{populateBookingForm(document.querySelector('#clientTrip').value);renderAvailability()});document.querySelector('#clientDate').addEventListener('change',renderAvailability);document.querySelector('#clientBookingForm input[name=seats]').addEventListener('input',renderAvailability);document.querySelector('#menuToggle').addEventListener('click',()=>document.querySelector('#mainNav').classList.toggle('open'));document.querySelectorAll('#mainNav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('#mainNav').classList.remove('open')));
document.querySelector('#reviewForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form);try{if(apiMode){await apiRequest('review.submit',{name:fd.get('name'),trip:fd.get('trip'),rating:Number(fd.get('rating')),body:fd.get('body')})}else{state.reviews.unshift({id:'review-'+Date.now(),name:fd.get('name'),trip:fd.get('trip'),rating:Number(fd.get('rating')),body:fd.get('body'),status:'pending'});saveState();renderApprovedReviews()}form.reset();document.querySelector('#reviewFeedback').textContent='Thanks for sharing. Your review is waiting for the Nyathi Tours team to approve it.';notify('Review submitted for approval.')}catch(err){document.querySelector('#reviewFeedback').textContent=err.message;notify(err.message)}});
document.querySelector('#clientTrip').addEventListener('change',()=>populateBookingForm());
document.querySelector('#clientBookingForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),trip=tripById(fd.get('trip')),packageSelect=document.querySelector('#clientPackage'),opt=packageSelect.selectedOptions[0];if(!trip||!opt)return;if(apiMode){try{const result=await apiRequest('booking.create',{name:fd.get('name'),phone:fd.get('phone'),email:fd.get('email'),trip:trip.id,date:fd.get('date'),pickup:fd.get('pickup'),seats:Number(fd.get('seats')),notes:fd.get('notes'),package_index:packageSelect.selectedIndex,package_label:opt.textContent});form.reset();populateBookingForm(trip.id);const feedback=document.querySelector('#bookingFeedback');feedback.className='request-success';feedback.textContent=`Request ${result.booking.requestNumber} has been sent to Nyathi Tours. The owner will check availability and contact you.`;notify('Booking request sent.')}catch(err){document.querySelector('#bookingFeedback').textContent=err.message;notify(err.message)}return}const requestNumber=`NT-R-${new Date().getFullYear()}-${String(state.bookings.length+1).padStart(4,'0')}`;const request={id:'request-'+Date.now(),requestNumber,name:fd.get('name'),phone:fd.get('phone'),email:fd.get('email'),trip:trip.id,packageLabel:opt.textContent,requestedPrice:Number(opt.dataset.price||trip.price),requestedDeposit:Number(opt.dataset.deposit||0),date:fd.get('date'),pickup:fd.get('pickup'),seats:Number(fd.get('seats')),notes:fd.get('notes'),status:'pending',requestedAt:new Date().toISOString()};state.bookings.unshift(request);saveState();form.reset();populateBookingForm(trip.id);const feedback=document.querySelector('#bookingFeedback');feedback.className='request-success';feedback.innerHTML=`Request <b>${esc(requestNumber)}</b> saved in this local preview. The owner can now review it in Owner preview → Bookings &amp; confirmations. This demonstration does not send the request to Nyathi Tours yet.`;notify('Booking request saved in this preview.')});
document.querySelector('#demoOwnerEnter').addEventListener('click',()=>{if(!demoReviewEnabled||apiMode)return;showOwnerDashboard();notify('Demo owner dashboard — changes stay in this browser.')});
document.querySelector('#year').textContent=new Date().getFullYear();renderTrips();syncPublicFromApi();if(demoReviewEnabled&&demoOwnerRoute)showOwner();
const printCss=document.createElement('style');printCss.textContent='@media print{body>*{display:none!important}#invoicePrint{display:block!important}.print-invoice{font:14px Arial,sans-serif;color:#111;padding:35px;max-width:760px;margin:auto}.print-brand{font-size:20px;font-weight:bold;color:#1c61c2}.print-invoice h1{font-size:32px;margin:35px 0 20px}.print-invoice table{width:100%;border-collapse:collapse;margin:30px 0}.print-invoice th,.print-invoice td{text-align:left;border-bottom:1px solid #aaa;padding:12px}.print-invoice th:last-child,.print-invoice td:last-child{text-align:right}.print-invoice footer{margin-top:45px;border-top:1px solid #aaa;padding-top:12px}.print-invoice small{display:block;margin-top:30px;color:#666}}';document.head.append(printCss);
